'use strict';
Object.assign(iconPaths,{pin:'M9 3h6l-1 6 4 4v2H6v-2l4-4-1-6 M12 15v6',plus:'M12 5v14 M5 12h14',check:'m5 12 4 4L19 6',leaf:'M20 4C5 2 2 10 6 16s15 3 14-12Z M6 18 16 8'});
const APP_VERSION='__APP_VERSION__';
const RELEASES=[{version:'__APP_VERSION__',title:'Checklist dễ xem và dễ sửa',text:'Mỗi mục checklist là một thẻ bo tròn, có nút lên/xuống để đổi thứ tự bằng chạm hoặc bàn phím, ô thêm mục gọn một dòng nhấn Enter để thêm, chữ dài không còn bị cắt.'},{version:'1.17.3',title:'Bảng Tất cả công việc dễ lọc và dễ quét',text:'Thêm chip lọc nhanh có số lượng (Tất cả, Hôm nay, Quá hạn, Sắp đến hạn, Đang thực hiện) và làm bảng công việc dễ quét hơn: trạng thái thẳng hàng có chấm màu, hàng quá hạn tô nhẹ.'},{version:'1.17.2',title:'Ghi chú ghim nhanh dễ nhìn hơn',text:'Khu Ghi chú ghim nhanh ở thanh bên có ô màu theo màu ghi chú, tên, dòng xem trước, nút bỏ ghim dạng biểu tượng và lối tắt Tất cả ghi chú.'},{version:'1.17.1',title:'Thông báo gọn và dễ quét hơn',text:'Hộp thoại Thông báo gom việc theo nhóm Quá hạn, Sắp đến hạn, Quan trọng với số lượng, mỗi việc một hàng gọn; thanh nhắc hạn và hộp Công việc cần chú ý có màu theo mức độ.'},{version:'1.17.0',title:'Nút chế độ sáng/tối cạnh chuông',text:'Thêm nút chuyển nhanh giao diện sáng/tối ngay cạnh biểu tượng thông báo trên thanh trên cùng, dùng được trên điện thoại, máy tính bảng và máy tính.'},{version:'1.16.6',title:'Gỡ chế độ xem Dòng thời gian',text:'Bỏ hoàn toàn chế độ xem Dòng thời gian khỏi menu, thanh chế độ xem trên điện thoại và hướng dẫn. Còn Bảng Kanban, Lịch và Gantt; dữ liệu ngày của công việc giữ nguyên.'},{version:'1.16.5',title:'Lời chào hiện đủ 4 buổi trong ngày',text:'Sửa lỗi lời chào Chào mừng bạn trở lại không hiện lại ở các buổi sáng, trưa, chiều, tối sau khi đã bấm đã đọc một lần.'},{version:'1.16.4',title:'Xóa Thùng rác không cần mật khẩu',text:'Dọn sạch Thùng rác, xóa vĩnh viễn từng mục và xóa tệp đính kèm trong Thùng rác không còn đòi nhập lại mật khẩu, nên bấm Đồng bộ cũng không bị hỏi nữa; vẫn có hộp xác nhận và cảnh báo không thể hoàn tác. Chia sẻ vẫn cần mật khẩu.'},{version:'1.16.3',title:'Xóa dự án đúng dự án',text:'Nút Xóa dự án này trong biểu mẫu dự án nay xóa đúng dự án đang được sửa, không còn dựa vào dự án đang mở phía sau. Cách mở biểu mẫu, hộp xác nhận và việc chuyển vào Thùng rác không đổi.'},{version:'1.16.2',title:'Chế độ tối hoàn thiện hơn',text:'Biểu đồ Gantt và vòng Bức tranh công việc đã có nền tối, nhãn ngày sáng rõ. Nút Làm mới ở Chế độ tập trung không còn bị trắng khi bật tương phản cao. Chỉ đổi giao diện tối và tương phản cao; dữ liệu và chế độ sáng không đổi.'},{version:'1.16.1',title:'Khởi động ổn định hơn',text:'Ứng dụng báo rõ khi đã khởi động xong, để màn hình đăng nhập và các thao tác ngay sau khi mở không bị xóa nhầm bởi bước tải dữ liệu còn đang chạy. Dữ liệu và giao diện không đổi.'},{version:'1.16.0',title:'Chế độ tối và tương phản cao',text:'Giao diện có thêm chế độ tối và tương phản cao. Mặc định theo cài đặt của thiết bị; có thể chọn tay trong Cài đặt → Giao diện hoặc bằng Ctrl+K. Lựa chọn chỉ lưu trên thiết bị này, không ảnh hưởng dữ liệu.'},{version:'1.15.54',title:'Dọn mã giao diện (đợt 1)',text:'Gỡ 51 khai báo giao diện thừa đã bị ghi đè hoàn toàn và đặt ngân sách để số quy tắc ép buộc không tăng lại. Giao diện không đổi; đây là bước chuẩn bị cho chế độ tối.'},{version:'1.15.53',title:'Nút xóa việc và dự án tinh tế hơn',text:'Khu vực xóa việc và xóa dự án có biểu tượng thùng rác, tiêu đề và lời giải thích rõ (chuyển vào Thùng rác, khôi phục được trong 30 ngày), nút viền đỏ nhạt thay vì khối đỏ đặc. Cách xóa và xác nhận không đổi.'},{version:'1.15.52',title:'Việc hoàn thành chìm xuống',text:'Thẻ việc ở cột Hoàn thành được rút màu, nền xám nhạt, tiêu đề gạch ngang và nhãn chuyển xám để mắt không phải chú ý tới nữa. Chữ vẫn rõ, đưa chuột hoặc chọn thẻ thì thẻ hiện lại đầy đủ.'},{version:'1.15.51',title:'Ghim ghi chú rõ ràng hơn',text:'Khu vực ghim trong ghi chú có biểu tượng minh họa, tiêu đề và mô tả cho từng kiểu ghim (lên đầu danh sách, ghim nhanh ở menu). Ghim đang bật đổi màu nổi bật, nút to dễ bấm trên điện thoại. Cách ghim và bỏ ghim không đổi.'},{version:'1.15.50',title:'Bỏ họa tiết ở dự án và việc',text:'Dự án và việc không còn lựa chọn họa tiết, thẻ và trang không còn vẽ họa tiết nền nên dễ đọc hơn. Họa tiết bạn đã chọn trước đây vẫn được giữ trong dữ liệu, không bị xóa hay ghi đè khi lưu. Ghi chú vẫn có họa tiết như cũ.'},{version:'1.15.49',title:'Lịch dạng danh sách cho màn hình vừa',text:'Ở máy tính bảng, trang Lịch hiện theo danh sách từng ngày dễ đọc thay cho lưới 7 cột chật; có nút đổi qua lại giữa Danh sách và Lưới tháng, và máy nhớ lựa chọn của bạn.'},{version:'1.15.48',title:'Gantt dễ kéo bằng ngón tay',text:'Trên màn hình cảm ứng, đầu kéo và nút nối của biểu đồ Gantt có vùng chạm 44px nên kéo dời lịch hoặc nối phụ thuộc bằng ngón tay không còn trượt; trên chuột mọi thứ giữ nguyên.'},{version:'1.15.47',title:'Hộp thoại còn lại dễ chạm hơn',text:'Sáu hộp thoại trước đây chưa được kiểm tra truy cập (báo cáo tuần, chia sẻ báo cáo, chọn ngày, lời chào, tải tệp, thanh lệnh) nay đã được quét; nút Tháng trước/Tháng sau của bảng chọn ngày và nút Đóng lời chào được nới lên 44px trên màn hình cảm ứng. Không đổi dữ liệu.'},{version:'1.15.46',title:'Một nơi báo sự cố đồng bộ',text:'Khi đồng bộ gặp sự cố (máy chủ từ chối, dữ liệu không hợp lệ, xung đột), thông báo nổi không còn nói lại điều viên thuốc và khung báo lỗi đã nói; khung có thêm một dòng trấn an rằng bản nháp vẫn ở thiết bị. Dòng tự lưu của ghi chú và vài thông báo còn lại dùng chung chữ trên thiết bị. Không đổi dữ liệu và cách đồng bộ.'},{version:'1.15.45',title:'Thẻ gọn và checklist khớp nhau',text:'Khi Thẻ gọn đang ẩn checklist trên thẻ, ô Hiện checklist trên thẻ trong menu Hiển thị nay bỏ dấu, bị khóa và ghi rõ lý do thay vì vẫn đánh dấu như đang hiện. Lựa chọn bạn đã lưu không bị đổi và trở lại khi tắt Thẻ gọn. Không đổi dữ liệu.'},{version:'1.15.44',title:'Một trạng thái lưu',text:'Trạng thái lưu và đồng bộ nay dùng một bộ chữ và một cách phân loại ở mọi nơi: viên thuốc ở thanh trên, khung báo lỗi bên dưới và dòng trạng thái trong hộp thoại chi tiết việc cùng nói một điều. Nhãn lỗi không còn lặp chữ Chưa đồng bộ; khi máy chủ lỗi mà vẫn có mạng thì ghi Chưa kết nối được thay vì Ngoại tuyến; viên thuốc dùng nhãn ngắn, khung lỗi nêu đầy đủ kèm nút Thử lại, không lặp một câu hai lần. Bỏ nhãn Báo cáo đồng bộ không bấm được ở chân thanh bên (báo cáo vẫn nằm trong Cài đặt). Không đổi dữ liệu và cách đồng bộ.'},{version:'1.15.43',title:'Một kênh nhắc việc',text:'Việc quá hạn và việc đến hạn trong 3 ngày nay nhắc chủ yếu ở một nơi là thanh nhắc đầu trang; số trên chuông bằng đúng số ở thanh đó (trước đây thanh nhắc, chuông và thông báo nổi mỗi nơi một số, và thông báo nổi lặp lại cùng tin mỗi giờ). Thông báo nổi chỉ hiện khi có việc mới đến hạn, không lặp lại. Phiên bản mới, tệp mới và nhắc ghi chú báo bằng một chấm nhỏ cạnh chuông, không cộng vào số. Hộp thoại Thông báo mở đầu bằng một dòng tóm tắt khớp với số trên chuông. Không đổi dữ liệu.'},{version:'1.15.42',title:'Danh sách việc gọn hơn',text:'Màn hình Tất cả công việc gọn hơn: mỗi việc một hàng thấp (khoảng 53px trên máy tính, 123px trên điện thoại thay vì 309px), tên dự án nằm ngay dưới tên việc, ngày và ưu tiên là chip bấm để sửa. Không còn nhãn Hạn chót lặp ở từng hàng; việc quá hạn ghi một lần, việc đã xong nằm cuối danh sách. Có dòng giải thích ô vuông dùng để chọn nhiều việc. Không đổi dữ liệu.'},{version:'1.15.41',title:'Dễ chạm, dễ dùng bàn phím',text:'Hộp thoại thêm việc, dự án mới và ghi chú mới mở vào thẳng ô tên (trên điện thoại, việc đã có thì không bật bàn phím); mọi hộp thoại có tên để trình đọc màn hình đọc. Trên màn hình cảm ứng, nút, ô chọn và ô nhập chính cao tối thiểu 44px; ở mọi thiết bị mỗi điều khiển tối thiểu 24px. Chi tiết việc trên điện thoại: phím Tab đi đúng thứ tự nhìn. Sửa tiêu đề trùng chữ ở hộp thoại Cài đặt. Không đổi dữ liệu.'},{version:'1.15.40',title:'Chữ dễ đọc hơn',text:'Chữ nhỏ nhất nay là 12px (trước có chỗ chỉ 8–11px); chữ phụ, nhãn, hạn và tab dùng màu đậm hơn để đạt tương phản tối thiểu 4,5:1; nút tím–hồng sẫm hơn để chữ trắng đọc rõ; viền ô nhập và chữ gợi ý rõ hơn. Thẻ Hoàn thành và tab dự án không chọn không còn bị làm mờ cả chữ. Không đổi dữ liệu.'},{version:'1.15.39',title:'Từ ngữ giao diện thống nhất',text:'Giao diện dùng một bộ từ tiếng Việt: Bảng Kanban, Dòng thời gian, Lịch, Cài đặt, việc (thay cho task), Hoàn thành (thay cho Done) và Giới hạn việc mỗi cột (thay cho WIP). Ô Cột trong biểu mẫu việc hiện tên cột đang dùng thay vì Idea, List, Doing, Done. Thanh chế độ xem trên điện thoại hiện đủ tên mới nên cao hơn vài điểm ảnh. Không đổi dữ liệu.'},{version:'1.15.38',title:'Thẻ gọn mặc định trên điện thoại',text:'Trên điện thoại, thẻ công việc mặc định ở chế độ gọn (ẩn mô tả, checklist và bước tiếp theo) để cột ngắn lại và ít phải cuộn; có thể chọn Thẻ gọn tắt trong menu Hiển thị và lựa chọn đó được giữ. Màn hình rộng vẫn mặc định thẻ đầy đủ. Không đổi dữ liệu.'},{version:'1.15.37',title:'Gom nút phụ vào menu Hiển thị',text:'Thẻ gọn, Giới hạn WIP và Lệnh nhanh nằm trong menu Hiển thị của dự án thay vì một hàng nút riêng dưới khối tiến độ, nên thẻ đầu tiên lên cao hơn. Các nút vẫn làm việc như cũ; Ctrl/⌘ K vẫn mở Lệnh nhanh. Không đổi dữ liệu.'},{version:'1.15.36',title:'Đầu trang dự án gọn hơn',text:'Đầu trang dự án chỉ còn một nút chính là Thêm việc; Ghim, Lưu trữ, Tệp và Sửa dự án nằm trong menu Tùy chọn. Khối tiến độ ghi rõ số việc đã xong (ví dụ 3/14 việc xong) cùng phần trăm. Trên điện thoại thẻ đầu tiên hiện ngay trong màn hình đầu. Không đổi dữ liệu.'},{version:'1.15.35',title:'Thẻ Kanban gọn hơn',text:'Nút chuyển nhanh thu thành mũi tên cạnh hạn thay vì một hàng riêng ở mỗi thẻ; việc chưa có checklist không còn hiện 0% và thanh tiến độ trống; khoảng cách trong thẻ chặt hơn. Thẻ thấp hơn khoảng 43%. Không đổi dữ liệu.'},{version:'1.15.34',title:'Khung điều hướng ổn định',text:'Từ màn hình 701px, thanh trên (ô tìm kiếm, trạng thái đồng bộ) và dải tab dự án luôn nằm ở đầu màn hình khi cuộn; chuyển màn hình thì về đầu trang. Đường dẫn của trang Lưu trữ và Thùng rác không còn trống. Không đổi dữ liệu.'},{version:'1.15.33',title:'Sửa bố cục tablet',text:'Tên dự án và tiêu đề trang không còn bị bóp thành từng chữ ở màn hình 701–1000px; phần trăm tiến độ trên tab không còn bị bẻ dòng; thanh trên không còn tràn ngang. Không đổi dữ liệu.'},{version:'1.15.32',title:'Lịch gọn hơn cho task dài ngày',text:'Task nhiều ngày hiện thành một thanh liền xuyên các ngày trong tuần thay vì lặp một thẻ ở mỗi ngày. Không đổi dữ liệu.'},{version:'1.15.31',title:'Sửa giao diện thẻ công việc',text:'Nút chuyển nhanh nằm gọn trong thẻ, không còn tràn ra ngoài; họa tiết phủ nhẹ lên nền thẻ thay cho ô vuông lệch. Không đổi dữ liệu.'},{version:'1.15.30',title:'Tài liệu khớp thực tế',text:'Cập nhật tài liệu dự án cho đúng cách phát hành và triển khai. Không đổi tính năng, dữ liệu hay giao diện.'},{version:'1.15.29',title:'Ghim nhanh ghi chú và task',text:'Tách Ghim ghi chú và Ghim nhanh; tối đa 3 ghi chú ghim nhanh trên thanh tab, mục Pin trong menu dành cho task. Họa tiết ghi chú phủ nhẹ từng thẻ và khung soạn.'},{version:'1.15.25',title:'Ghim nhanh ghi chú và task',text:'Thêm truy cập nhanh ghi chú và ghim task trong menu.'},{version:'1.15.24',title:'Mobile calendar, checklist và dự án',text:'Cải thiện lịch mobile, checklist, họa tiết dự án và xác nhận khôi phục.'},{version:'1.14.7',title:'Gantt linh hoạt, báo cáo rõ ràng',text:'Tạo công việc trực tiếp từ ngày trên Gantt và sắp xếp nhanh các việc chưa có lịch. Căn chỉnh nút Focus gọn hơn; cải thiện cách trình bày phân bố trạng thái, tổng kết dự án và nhịp tuần trong báo cáo PDF.'},{version:'1.14.6',title:'Báo cáo rõ ràng, lịch gọn nhẹ',text:'Tối ưu bố cục in và lưu PDF; chia sẻ báo cáo mặc định công khai trong 1 ngày. Gõ 1. hoặc * rồi Space để tạo danh sách và tiếp tục bằng Enter. Lịch task dùng ngày bắt đầu/kết thúc, trong đó ngày kết thúc là hạn; nút Focus có chú thích và căn chỉnh gọn hơn.'},{version:'1.14.4',title:'Dự án rõ nhịp, tập trung dễ hơn',text:'Ngày và họa tiết dự án, Timeline gọn trong thẻ, truy cập tập trung nhanh, kiểm tra dữ liệu tự động và thủ công. Cải thiện nút Lưu, menu danh sách, liên kết ghi chú, bộ lọc và chi tiết báo cáo web.'},{version:'1.14.3',title:'Lời chào nhẹ nhàng, thông báo đồng bộ',text:'Làm gọn lời chào; xác nhận đã đọc theo tài khoản trên mọi thiết bị. Thêm 30 lời khích lệ khi hoàn thành việc, sửa khung mô tả và Timeline, bổ sung họa tiết Nông trại, Gia đình, Tài chính cho ghi chú và công việc.'},{version:'1.14.2',title:'Khôi phục mốc đồng bộ',text:'Khôi phục phiên bản đồng bộ bị thiếu bằng hợp nhất an toàn. Phân biệt lỗi mốc phiên bản với nội dung, hiển thị phản hồi cụ thể từ máy chủ.'},{version:'1.13.2',title:'Giữ an toàn bản nháp',text:'Giữ bản nháp chưa đồng bộ khi mở lại tài khoản; báo rõ dung lượng hoặc dữ liệu chưa hợp lệ. Lịch sử ghi chú có thể xem khi bản nháp đang chờ; tinh gọn bộ lọc và giao diện tập trung.'},{version:'1.13.1',title:'Gọn lựa chọn, rõ trạng thái',text:'Bộ lọc dạng nhãn màu bo tròn, Cài đặt chia nhóm, nút thêm checklist canh phải. Dọn Thùng rác chờ đồng bộ đang chạy và trả kết quả rõ ràng.'},{version:'1.13.0',title:'Một việc mỗi lúc',text:'Chế độ tập trung gom việc đến hạn, quá hạn và gợi ý ba ưu tiên. Ghi chú liên kết xuất hiện trong dự án, mô tả dự án có định dạng và lựa chọn liên kết được thu gọn.'},{version:'1.12.1',title:'Gọn bộ lọc, rõ công việc',text:'Bộ lọc thu gọn, bình luận rộng hơn, liên kết từ ghi chú sang công việc/dự án. Ghi nhớ dự án gần nhất và nhấn mạnh tab đang xem; kết quả tìm kiếm có từ khóa nổi bật.'},{version:'1.12.0',title:'Làm việc liền mạch hơn',text:'Giữ vị trí checklist khi sắp xếp; thêm mẫu công việc, bình luận, nhãn trạng thái và liên kết ghi chú. Đồng bộ rõ ràng trên mobile, lịch sử ghi chú dạng dòng thời gian và thao tác nhiều task.'},{version:'1.11.2',title:'Củng cố logic, gọn mã nguồn',text:'Gom logic hiển thị trùng, dọn listener khi đóng form, thống nhất luồng tự lưu ghi chú. Kéo thả bỏ qua vị trí không hợp lệ và thao tác không thay đổi; kiểm tra tên cột ở trình duyệt và máy chủ.'},{version:'1.11.1',title:'Tinh chỉnh không gian làm việc',text:'Số ghi chú theo từ khóa, lịch sử 7 ngày gọn hơn, nút đồng bộ mobile, thông báo đã xem và đổi tên cột Kanban.'},{version:'1.11.0',title:'Giữ nhịp làm việc quen thuộc',text:'Chuyển và copy task giữa dự án, lưu trữ task, định dạng mô tả, thêm và sắp xếp checklist nhanh. Ghi chú tự lưu đầy đủ và kéo thả bằng tay nắm.'},{version:'1.10.2',title:'Ảnh ghi chú gọn gàng',text:'Sửa ảnh đính kèm còn sót sau khi gỡ để thẻ ghi chú giữ bố cục ổn định; tự ẩn ảnh tải lỗi.'},{version:'1.10.1',title:'Tệp đính kèm gọn gàng',text:'Nhóm ảnh riêng khỏi tài liệu và các loại tệp khác; thu nhỏ ảnh xem trước theo khung, tên tệp dễ đọc và gỡ tệp ngay tại chỗ. Ảnh xem trước liên kết có hình dự phòng khi tệp ảnh không tải được. Đồng bộ số phiên bản 1.10.1 trên toàn ứng dụng.'},{version:'1.9.11',title:'Đồng bộ an tâm',text:'Sửa trạng thái đồng bộ kéo dài và cảnh báo sai, phân biệt lưu cục bộ/chờ mạng/dữ liệu bị từ chối; có giới hạn thời gian chờ và nút thử lại, không tự ghi đè bản khác.'},{version:'1.9.10',title:'Họa tiết an nhiên',text:'Nút ghim/bỏ ghim có hàng riêng, không đè lên tiêu đề ghi chú. Nâng cấp tám tranh nền thiên nhiên và thiền, thêm ảnh mẫu thu nhỏ để chọn trực quan, tương phản chữ rõ trên desktop/mobile.'},{version:'1.9.9',title:'Soạn thảo trực tiếp',text:'Định dạng ngay trong vùng nhập ghi chú; cải thiện tìm kiếm theo nhóm và sửa trạng thái, cơ chế đồng bộ dữ liệu tự động.'},{version:'1.9.8',title:'Ghi chú sinh động',text:'Ghim ghi chú như Keep, tìm tệp và nội dung toàn dự án, họa tiết minh họa toàn thẻ, thanh định dạng văn bản, thumbnail và sửa nút đóng.'},{version:'1.9.7',title:'Checklist nở hoa',text:'Checklist ghi chú có nút Thêm mục lưu tự động, thanh tiến độ trực quan và tám họa tiết thiên nhiên, thiền, yoga, tỉnh thức trên từng thẻ.'},{version:'1.9.6',title:'Tìm kiếm ghi chú mở rộng',text:'Mở kết quả ghi chú từ thanh tìm kiếm chung và tối ưu giao diện nhập liệu trên điện thoại.'},{version:'1.9.5',title:'Ghi chú & Tài nguyên',text:'Gom ba tùy chọn ghi chú trên desktop, thu gọn thanh tab dự án và tải tệp ngay trong Tài nguyên.'},{version:'1.9.4',title:'Giao diện linh hoạt',text:'Cải thiện hộp thoại, nút đóng và tab dự án trên nhiều kích thước màn hình.'},{version:'1.9.3',title:'Ghi chú gọn, sáng rõ',text:'Tối ưu nhập ghi chú trên Mobile: khung soạn vừa màn hình, giảm chiều cao các trường, nhóm tùy chọn phụ, sửa vị trí hiển thị và dễ lưu khi chạm.'},{version:'1.9.2',title:'Học sâu, trở về mình',text:'Bổ sung 261 trích đoạn có nguồn: Mạnh Tử, Nam Hoa Kinh, Tuân Tử và các nguồn chính thức. Lưu nguyên bản, vị trí chương và bản tiếng Việt; phân biệt lời nhân vật trong tác phẩm với phát ngôn lịch sử.'},{version:'1.9.1',title:'Lời có nguồn, ngày có nhịp',text:'Bổ sung 185 trích đoạn có nguồn và bản tiếng Việt; toàn bộ trích đoạn tham gia vòng chọn, không lặp trong một chu kỳ. Lời biên soạn được giữ riêng và không tính vào mục tiêu 3.333.'},{version:'1.9.0',title:'Bốn mùa trong ngày',text:'Lời chào theo bốn buổi giờ Việt Nam, hồ sơ tư tưởng, nguồn tham khảo và chân dung tư liệu của các vị thầy.'},{version:'1.8.4',title:'Task cuộn liền mạch',text:'Thanh đầu của cửa sổ task cuộn cùng nội dung, giúp tập trung đọc và chỉnh sửa.'},{version:'1.8.3',title:'Chữ rõ, việc nhẹ',text:'Tinh chỉnh font nhãn dự án và nội dung task để dễ đọc trên desktop, tablet và điện thoại.'},{version:'1.8.2',title:'Nhịp việc rõ ràng',text:'Thông báo đến hạn cuộn theo trang; báo cáo có khoảng lề rõ ràng; nhãn dự án theo màu; lưu task và đóng form, bấm thanh Gantt để sửa trực tiếp.'},{version:'1.8.1',title:'Thanh âm ngày mới',text:'Nhạc nền Bamboo at Daybreak có nút phát, tạm dừng, âm lượng và màu tương phản theo nền. Phiên bản tự cập nhật trên màn hình đăng nhập.'},{version:'1.8.0',title:'Chia sẻ điều đang lớn',text:'Chia sẻ báo cáo qua web công khai hoặc có mật khẩu, chọn hạn 1–30 ngày và thu hồi. Mở rộng thư viện icon theo nhóm, tìm tiếng Anh; ghi chú có bánh xe màu HEX/RGB.'},{version:'1.7.0',title:'Dòng việc liền mạch',text:'Kéo đổi lịch Gantt trực tiếp, checklist ngay trên thẻ, ghi chú có từ khóa và email nhắc hạn, Thùng rác theo lưới/danh sách cùng thống kê và xóa có xác nhận.'},{version:'1.6.3',title:'Chạm để hiểu',text:'Các ô thống kê mở danh sách và tiến độ chi tiết, hiệu ứng chuyển động nhẹ, thanh nhắc hạn dễ thao tác và ảnh hồ sơ hiển thị tại avatar.'},{version:'1.6.2',title:'Nhịp an nhiên',text:'Form ghi chú và công việc rõ ràng, Mức độ bốn màu, font mềm mại, biểu đồ tròn trong PDF và phiên làm việc tự khóa sau 10 phút không thao tác.'},{version:'1.6.1',title:'Thông báo mở đúng chi tiết',text:'Nút Xem chi tiết mở phiên bản hoặc công việc liên quan, đồng bộ icon Dashboard mềm mại và thu gọn phiên bản cuối trang.'},{version:'1.6.0',title:'Gantt, ghi chú và tài nguyên',text:'Gantt có liên kết phụ thuộc và chặn vòng lặp; mở trực tiếp ghi chú, khung soạn bo tròn, tìm icon tiếng Anh và đổi tên tài nguyên.'},{version:'1.5.0',title:'Điều hướng & không gian làm việc tinh tế',text:'Kéo sắp xếp tab, tiến độ dự án đa chế độ, từ khóa dự án, lịch chọn ngày giờ, xác nhận lưu trữ và danh sách việc cần chú ý.'},{version:'1.4.1',title:'Checklist gọn & thư viện tài nguyên',text:'Checklist một dòng, tổng kết email có biểu đồ % và tiến độ từng dự án, xem trước/In/Lưu PDF, album Tài nguyên riêng tư quản lý tệp.'},{version:'1.4.0',title:'Bức tranh công việc & tổng kết tuần',text:'Biểu đồ tương tác bốn màu, nhắc hạn trước 3 ngày, email tổng kết Chủ nhật trong Settings, bảng icon và bánh xe HEX/RGB. Lưu trữ dự án đang làm dở.'},{version:'1.3.8',title:'Lời chào mỗi ngày tinh gọn hơn',text:'Lược bỏ phần hiển thị bản dịch và bản tiếng Anh, cải thiện kiểu chữ, căn dòng và nút đóng.'},{version:'1.3.7',title:'Ma trận ưu tiên bốn màu',text:'Cập nhật bốn nhãn theo mức độ quan trọng và khẩn cấp: tím, xanh lá, hồng và cam.'},{version:'1.3.6',title:'Toàn cảnh & công việc trong một màn hình',text:'Thống kê quá hạn, tổng quan đầu trang mobile, chỉnh task trực tiếp, ma trận bốn màu, tùy chọn Kanban và tiến độ Timeline/Calendar. Hướng dẫn đầy đủ.'},{version:'1.3.4',title:'Thông báo đã xem & chuyển bước công việc',text:'Nút Đã xem tất cả đưa bộ đếm về bình thường. Chuyển task sang cột kế tiếp ngay trên thẻ.'},{version:'1.3.3',title:'Ghi chú trực tiếp & lời chào mỗi ngày',text:'Viết ghi chú, thêm liên kết và tải tệp trong cùng khung. Lời chào hằng ngày có họa tiết thiên nhiên.'}];
let latestVersion=APP_VERSION;
function localRead(k){try{return localStorage.getItem(k);}catch{return null;}}
function localWrite(k,v){try{localStorage.setItem(k,v);}catch{}}
// Read receipts belong to the signed-in account, independently of workspace revisions.
let readReceiptOwner=null,readReceiptKeys=new Set(),readReceiptLoaded=false,readReceiptRequest=null,readReceiptTime=0;
function noticeReceipt(t){return 'notice:'+encodeURIComponent(noticeSignature(t));}
async function loadReadReceipts(force=false){
 const owner=currentUser?.id;if(!owner)return false;
 if(readReceiptOwner!==owner){readReceiptOwner=owner;readReceiptKeys=new Set();readReceiptLoaded=false;readReceiptRequest=null;readReceiptTime=0;}
 if(readReceiptRequest)return readReceiptRequest;
 if(readReceiptLoaded&&!force&&Date.now()-readReceiptTime<10000)return true;
 const pending=(async()=>{try{const result=await requestAPI('notification-receipts');if(currentUser?.id!==owner||readReceiptOwner!==owner)return false;if(!Array.isArray(result.keys))throw Error('Invalid receipts');readReceiptKeys=new Set(result.keys.filter(k=>typeof k==='string'));readReceiptLoaded=true;readReceiptTime=Date.now();refreshBell();if(readReceiptKeys.has(welcomeReceipt(welcomeSlot())))document.querySelector('.welcome-dialog:not([data-manual])')?.close();return true;}catch{return false;}})();
 readReceiptRequest=pending;try{return await pending;}finally{if(readReceiptRequest===pending)readReceiptRequest=null;}
}
async function saveReadReceipts(keys){
 const owner=currentUser?.id;if(!owner)throw Error('Vui lòng đăng nhập.');
 for(let i=0;i<keys.length;i+=200)await requestAPI('notification-receipts','PUT',{keys:keys.slice(i,i+200)});
 if(currentUser?.id!==owner)throw Error('Tài khoản đã thay đổi.');
 if(readReceiptOwner!==owner){readReceiptOwner=owner;readReceiptKeys=new Set();readReceiptLoaded=false;}
 keys.forEach(key=>readReceiptKeys.add(key));refreshBell();
}
function releaseKey(){return 'zen-release-seen:'+currentUser?.id;}
function releaseUnread(){return !!currentUser&&!(readReceiptOwner===currentUser.id&&readReceiptKeys.has('release:'+latestVersion))&&localRead(releaseKey())!==latestVersion;}
const oldBellRefresh=refreshBell;refreshBell=function(){oldBellRefresh();if(releaseUnread()){const count=taskNotices().length+fileAlerts.length+1;bell.innerHTML=svgIcon('bell')+'<span class="notification-count">'+(count>99?'99+':count)+'</span>';bell.setAttribute('aria-label','Thông báo · '+count+' mục, có phiên bản mới');}};
const oldBellClick=bell.onclick;bell.onclick=()=>{oldBellClick();const list=$('#editor-body .notice-list');if(!releaseUnread())return;list.insertAdjacentHTML('afterbegin',`<article class="notice-item release-notice"><strong>${releaseUnread()?'Mới · ':''}Phiên bản ${esc(latestVersion)}</strong><span>${latestVersion===APP_VERSION?esc(RELEASES[0].text):'Có bản cập nhật mới. Tải lại trang để nhận tính năng mới nhất.'}</span><button class="btn" type="button" id="release-read">${svgIcon('notes')}Xem chi tiết</button>${latestVersion!==APP_VERSION?'<button class="btn" id="release-reload" type="button">Tải lại trang</button>':''}</article>`);$('#release-read').onclick=async e=>{e.currentTarget.disabled=true;try{await saveReadReceipts(['release:'+latestVersion]);localWrite(releaseKey(),latestVersion);refreshBell();$('#editor').close();go('versions');}catch{notify('Chưa lưu được trạng thái đã đọc. Hãy thử lại.');e.target.closest('button').disabled=false;}};if($('#release-reload'))$('#release-reload').onclick=()=>location.reload();};
versions=()=>heading('NHẬT KÝ PHÁT TRIỂN','Phiên bản '+APP_VERSION,'Những thay đổi mới nhất')+'<section class="panel release">'+RELEASES.map(r=>`<div class="timeline-item"><h4>v${r.version} · ${esc(r.title)}</h4><p>${esc(r.text)}</p></div>`).join('')+'</section>';
async function checkRelease(){if(!currentUser||document.hidden||!navigator.onLine)return;try{const r=await fetch('/health',{cache:'no-store'});if(r.ok){const body=await r.json();if(/^\d+\.\d+\.\d+$/.test(body.version)){latestVersion=body.version;refreshBell();}}}catch{}}
let wisdomCache=null,teacherCache=null,welcomeLoading=false,welcomeSession=new Set();
function welcomeDay(){const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
function wisdomIndex(day,count){return Math.floor((Date.parse(day+'T00:00:00Z')-Date.parse('2026-10-24T00:00:00Z'))/86400000+count*1000)%count;}
// v1.16.5: dấu "đã đọc" của lời chào riêng cho từng buổi (ngày + buổi 0-3); trước đây chỉ một dấu 'welcome' vĩnh viễn nên bấm đọc một lần là các buổi sau không bao giờ hiện lại.
function welcomeReceipt(time){return 'welcome:'+time.day+':'+time.slot;}
function welcomeSlot(now=new Date()){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Ho_Chi_Minh',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',hourCycle:'h23'}).formatToParts(now),v=Object.fromEntries(parts.map(p=>[p.type,p.value])),hour=Number(v.hour),slot=hour<5?3:hour<11?0:hour<14?1:hour<18?2:3,calendarDay=v.year+'-'+v.month+'-'+v.day,day=hour<5?new Date(Date.parse(calendarDay+'T00:00:00Z')-86400000).toISOString().slice(0,10):calendarDay;return {day,slot,label:['Buổi sáng','Buổi trưa','Buổi chiều','Buổi tối'][slot],serial:Math.floor(Date.parse(day+'T00:00:00Z')/86400000)*4+slot};}
// Pure selection functions are embedded into welcome.js at build-authoring time.
// Every excerpt occurs exactly once in a complete cycle, including authors
// without a profile. Entries for each author are spread across the cycle.
function welcomeAllowed(entry) {
  return !/marcus\s+aurelius|stoic|khắc\s*kỷ|khac\s*ky|epictetus|seneca/i.test([entry.author,entry.name,entry.id,entry.school,entry.theme,entry.source].filter(Boolean).join(' '));
}
function welcomeProfile(author, profiles) {
  return profiles.filter(p => welcomeAllowed(p) && (author === p.name || author.startsWith(p.name + ' ·')))
    .sort((a,b) => b.name.length - a.name.length)[0];
}
function welcomeHash(s) {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619);
  return h >>> 0;
}
function welcomeDeck(quotes, profiles) {
  const groups = new Map();
  for (const quote of quotes) {
    if (!welcomeAllowed(quote) || typeof quote.vi !== 'string' || !quote.vi.trim()) continue;
    const profile = welcomeProfile(quote.author, profiles);
    const key = profile?.id || quote.author;
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push({quote,profile});
  }
  const deck = [];
  for (const [key, entries] of groups) {
    entries.sort((a,b) => welcomeHash(a.quote.id || a.quote.vi) - welcomeHash(b.quote.id || b.quote.vi)
      || a.quote.vi.localeCompare(b.quote.vi));
    entries.forEach((entry,i) => deck.push({...entry, position:(i+0.5)/entries.length,key}));
  }
  return deck.sort((a,b) => a.position - b.position || a.key.localeCompare(b.key));
}
let welcomeDeckCache=null,welcomeDeckQuotes=null,welcomeDeckProfiles=null;
function welcomeSelection(time) {
  const profiles=teacherCache?.profiles||[];
  if(welcomeDeckQuotes!==wisdomCache||welcomeDeckProfiles!==profiles){
    welcomeDeckCache=welcomeDeck(wisdomCache,profiles);
    welcomeDeckQuotes=wisdomCache;welcomeDeckProfiles=profiles;
  }
  if(!welcomeDeckCache.length)return {};
  const epoch=Math.floor(Date.parse('2026-10-24T00:00:00Z')/86400000)*4;
  const index=((time.serial-epoch)%welcomeDeckCache.length+welcomeDeckCache.length)%welcomeDeckCache.length;
  return welcomeDeckCache[index];
}

async function dailyWelcome(force=false){
 if(!currentUser||document.hidden||welcomeLoading||$('#editor').open||document.querySelector('.welcome-dialog'))return;
 const owner=currentUser.id,time=welcomeSlot(),key='zen-welcome:'+owner+':'+time.day+':'+time.slot;
 if(!force&&(localRead(key)||welcomeSession.has(key)))return;
 welcomeLoading=true;
 try{
  if(!await loadReadReceipts()||(!force&&readReceiptKeys.has(welcomeReceipt(time))))return;
  if(!wisdomCache){const response=await fetch('/wisdom.json');if(!response.ok)throw Error('wisdom');wisdomCache=(await response.json()).filter(q=>typeof q.vi==='string'&&q.vi.trim());}
  if(!teacherCache){const response=await fetch('/teachers.json');if(response.ok)teacherCache=await response.json();}
  if(currentUser?.id!==owner||$('#editor').open)return;
  const {quote:q,profile}=welcomeSelection(time);if(!q)return;
  const d=document.createElement('dialog');d.className='welcome-dialog';if(force)d.dataset.manual='true';d.setAttribute('aria-labelledby','welcome-title');
  d.innerHTML=`<button type="button" class="welcome-close" aria-label="Đóng lời chào" title="Đóng">×</button><div class="welcome-content"><header class="welcome-heading"><span class="welcome-lotus" aria-hidden="true">❀</span><p class="eyebrow">${esc(time.label)} · MỘT KHOẢNH KHẮC CHO BẠN</p><h2 id="welcome-title">Chào mừng bạn trở lại</h2><p class="welcome-intro">Dừng một nhịp, rồi bắt đầu điều có ý nghĩa.</p></header><blockquote lang="vi">${esc(q.vi)}</blockquote><div class="wisdom-teacher">${profile?.image?'<img src="'+esc(profile.image)+'" alt="'+esc(profile.imageAlt||profile.name)+'" width="48" height="48">':''}<span><strong>${esc(profile?.name||q.author)}</strong><small>${esc(profile?.theme||q.attribution||'Một điều để chiêm nghiệm')}</small></span></div><details class="welcome-sources"><summary>Nguồn & thông tin trích dẫn</summary><p class="wisdom-kind">${esc(q.translationNote||'Bản dịch tiếng Việt · tham khảo')}</p><p class="wisdom-author">${esc(q.attribution||q.author)}</p><a href="${esc(q.url)}" target="_blank" rel="noopener noreferrer">${esc(q.source)} ↗</a>${q.contextUrl?'<a href="'+esc(q.contextUrl)+'" target="_blank" rel="noopener noreferrer">Giải nghĩa trích đoạn ↗</a>':''}${profile?.imageSource?'<a href="'+esc(profile.imageSource)+'" target="_blank" rel="noopener noreferrer">Nguồn ảnh chân dung ↗</a>':''}<details class="wisdom-directory"><summary>Thư viện · ${wisdomCache.filter(q=>q.kind!=='reflection').length} trích đoạn có nguồn</summary><p>Bản dịch nghĩa mang tính tham khảo. Lời biên soạn của Zen Studio được ghi riêng, không phải phát ngôn của vị thầy.</p>${(teacherCache?.profiles||[]).filter(welcomeAllowed).map(p=>'<a href="'+esc(p.url)+'" target="_blank" rel="noopener noreferrer">'+esc(p.name)+' · '+esc(p.theme)+'</a>').join('')}</details></details><footer class="welcome-actions"><button type="button" class="btn primary" id="welcome-read">${svgIcon('check')}Đã đọc · Bắt đầu làm việc</button><small>Không tự hiện lại trên các thiết bị của bạn. Có thể mở lại từ Thông báo.</small><p id="welcome-read-status" role="status" hidden></p></footer></div>`;
  document.body.append(d);d.addEventListener('close',()=>d.remove());d.querySelector('.welcome-close').onclick=()=>d.close();
  const portrait=d.querySelector('.wisdom-teacher img');portrait?.addEventListener('error',()=>portrait.remove(),{once:true});
  d.querySelector('#welcome-read').onclick=async e=>{const button=e.currentTarget,status=d.querySelector('#welcome-read-status');button.disabled=true;try{await saveReadReceipts([welcomeReceipt(time)]);d.close();}catch{status.hidden=false;status.textContent='Chưa lưu được xác nhận. Kiểm tra kết nối rồi thử lại.';button.disabled=false;}};
  d.showModal();d.scrollTop=0;welcomeSession.add(key);localWrite(key,'seen');
 }catch{}finally{welcomeLoading=false;}
}
const beforeWelcomeRender=render;render=function(){beforeWelcomeRender();if(currentUser)loadReadReceipts();setTimeout(dailyWelcome,700);};
setInterval(checkRelease,300000);setInterval(dailyWelcome,60000);window.addEventListener('focus',()=>{checkRelease();dailyWelcome();});setTimeout(dailyWelcome,1000);refreshBell();
function noticeSignature(t){return [t.id,t.notice,t.due||'',t.title,t.important].join('|');}
function seenNotices(){let local=[];try{local=JSON.parse(localRead('zen-notices:'+currentUser?.id)||'[]');}catch{}return [...new Set([...local,...[...(readReceiptOwner===currentUser?.id?readReceiptKeys:[])].filter(k=>k.startsWith('notice:')).map(k=>{try{return decodeURIComponent(k.slice(7));}catch{return '';}})])];}
async function markNoticesRead(){await saveReadReceipts(['release:'+latestVersion,...taskNotices().map(noticeReceipt)]);localWrite('zen-notices:'+currentUser?.id,JSON.stringify(taskNotices().map(noticeSignature)));fileAlerts=[];localWrite(releaseKey(),latestVersion);refreshBell();}
refreshBell=function(){const seen=new Set(seenNotices()),count=taskNotices().filter(t=>!seen.has(noticeSignature(t))).length+fileAlerts.length+(releaseUnread()?1:0);bell.innerHTML=svgIcon('bell')+(count?'<span class="notification-count">'+(count>99?'99+':count)+'</span>':'');bell.setAttribute('aria-label','Thông báo · '+count+' chưa xem');};
const beforeReadBell=bell.onclick;bell.onclick=()=>{beforeReadBell();const b=$('#clear-file-alerts');b.textContent='Xác nhận đã đọc tất cả';const tools=document.createElement('div');tools.className='notice-read-toolbar';$('#editor-body .notice-list').before(tools);tools.append(b);b.onclick=async()=>{b.disabled=true;try{await markNoticesRead();$('#editor').close();}catch{b.disabled=false;notify('Chưa lưu được xác nhận. Kiểm tra kết nối rồi thử lại.');}};const open=document.createElement('button');open.type='button';open.className='btn welcome-reopen';open.textContent='❀ Một điều để chiêm nghiệm';open.onclick=()=>{$('#editor').close();dailyWelcome(true);};$('#editor-body').append(open);const seen=new Set(seenNotices());document.querySelectorAll('.notice-list [data-task]').forEach(el=>{const t=taskNotices().find(t=>t.id===el.dataset.task&&t.project.id===el.dataset.pid);if(t&&seen.has(noticeSignature(t)))el.closest('.notice-item')?.remove();});};
const beforeNextCard=taskCard;taskCard=function(t,p){const html=beforeNextCard(t,p),next=p.columns[p.columns.indexOf(t.col)+1];return next?html.replace('</article>',`<button type="button" class="btn task-next" data-next-task="${esc(t.id)}" data-next-project="${esc(p.id)}">${svgIcon('check')}Chuyển sang ${esc(next)} →</button></article>`):html;};
document.addEventListener('click',e=>{const b=e.target.closest('[data-next-task]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();const p=project(b.dataset.nextProject),t=p?.tasks.find(t=>t.id===b.dataset.nextTask);if(!t)return;const next=p.columns[p.columns.indexOf(t.col)+1];if(!next)return;t.col=next;if(next==='Done'){t.checks.forEach(c=>c.done=true);celebrateCompletion('task');}save();render();},true);
refreshBell();

// Opening a task notice marks only that notice as seen, then opens its task editor.
document.addEventListener('click',e=>{const target=e.target.closest('.notice-list [data-task]');if(!target)return;const notice=taskNotices().find(t=>t.id===target.dataset.task&&t.project.id===target.dataset.pid);if(notice){const seen=new Set(seenNotices());seen.add(noticeSignature(notice));saveReadReceipts([noticeReceipt(notice)]).catch(()=>{});localWrite('zen-notices:'+currentUser?.id,JSON.stringify([...seen]));refreshBell();}},true);



setInterval(()=>{if(currentUser&&!document.hidden)loadReadReceipts();},10000);
